parameters.jsCode:
const raw = $json.response;

let obj;
try {
  obj = JSON.parse(raw);
} catch (e) {
  throw new Error(`LLM returned non-JSON: ${raw}`);
}

// 지원 네트워크 → chainId 매핑
const networkToChainId = {
  "ethereum": 1,
  "bsc": 56,
  "polygon": 137,
  "arbitrum": 42161,
  "optimism": 10,
  "base": 8453,
  "avalanche": 43114
};

// 비EVM 코인 → 네트워크 매핑
const nonEvmCoins = {
  "BTC": "bitcoin",
  "XRP": "xrp",
  "SOL": "solana",
  "DOGE": "dogecoin",
  "ADA": "cardano",
  "DOT": "polkadot",
  "ATOM": "cosmos",
  "TRX": "tron"
};

const out = {
  intent: obj.intent ?? null,
  coin: obj.coin ?? null,
  txid: obj.txid ?? null,
  network: (obj.network || "ethereum").toLowerCase(),
};

// intent 검증
const intents = new Set(["deposit_delay", "wrong_deposit", "other"]);
if (!out.intent || !intents.has(out.intent)) {
  throw new Error(`Invalid intent: ${out.intent}`);
}

// txid 검증 (EVM: 0x+64hex, 비EVM: 64hex)
if (out.txid !== null) {
  const isEvmTxid = /^0x[a-fA-F0-9]{64}$/.test(out.txid);
  const isNonEvmTxid = /^[a-fA-F0-9]{64}$/.test(out.txid);
  if (!isEvmTxid && !isNonEvmTxid) {
    throw new Error(`Invalid txid: ${out.txid}`);
  }
}

// coin 정규화
if (typeof out.coin === "string") out.coin = out.coin.toUpperCase();

// coin 기반 네트워크 보정 (LLM이 기본값 ethereum으로 줬을 때)
if (out.coin && nonEvmCoins[out.coin] && out.network === "ethereum") {
  out.network = nonEvmCoins[out.coin];
}

// chainId 매핑 (비EVM이면 null)
out.chainId = networkToChainId[out.network] || null;
out.isEvmChain = out.chainId !== null;

return [{ json: out }];

const input = $('Switch').first().json;

// ❌ $json → ✅ $input.item.json
const currentItem = $input.item.json;

const apiStatus = currentItem.status ?? null;
const apiMessage = currentItem.message ?? null;
const receiptStatus = currentItem.result?.status ?? null;

const out = {
  intent: input.intent ?? null,
  coin: input.coin ?? null,
  txid: input.txid ?? null,
  action: null,
  onchain_status: null,
  api_status: apiStatus,
  api_message: apiMessage,
  receipt_status: receiptStatus,
};

if (apiStatus !== "1") {
  out.action = "manual_review_api_error";
  out.onchain_status = "api_error";
  return { json: out };  // ← 배열 아님!
}

if (receiptStatus === "1") {
  out.action = "review_exchange_crediting";
  out.onchain_status = "confirmed_success";
  return { json: out };
}

if (receiptStatus === "0") {
  out.action = "manual_review_failed_tx";
  out.onchain_status = "confirmed_failed";
  return { json: out };
}

out.action = "pending_confirmation";
out.onchain_status = "unknown";

return { json: out };

